    def patch_scan(self, scan_id: str, body: ScanPatch | dict[str, Any]) -> ScanOut:
        """PATCH /v1/scans/{scan_id} -- Patch Scan

        Advance a scan through its FSM.

        - `started_at = NOW()` the first time status becomes `running`.
        - `finished_at = NOW()` the first time status becomes a terminal state
          (`completed`, `failed`, `cancelled`).
        - Idempotent: a repeat PATCH with the same status is a no-op on the
          timestamps that are already set.
        - Emits `scan_started` / `scan_completed` / `scan_failed` only on an
          actual status transition (not on re-posts).
        """
        return self._request('PATCH', '/v1/scans/{scan_id}', path_params={'scan_id': scan_id}, body=body)

    def complete_scan(self, scan_id: str, body: ScanCompleteIn | dict[str, Any]) -> ScanOut:
        """POST /v1/scans/{scan_id}/complete -- Complete Scan
        """
        return self._request('POST', '/v1/scans/{scan_id}/complete', path_params={'scan_id': scan_id}, body=body)

    def fail_scan(self, scan_id: str, body: ScanFailIn | dict[str, Any]) -> ScanOut:
        """POST /v1/scans/{scan_id}/fail -- Fail Scan
        """
